const spec=$json,h={apikey:$env.SUPABASE_SERVICE_ROLE_KEY,Authorization:`Bearer ${$env.SUPABASE_SERVICE_ROLE_KEY}`,'Content-Type':'application/json',Prefer:'return=representation'};
const claim=await this.helpers.httpRequest({method:'PATCH',url:`${$env.SUPABASE_URL}/rest/v1/edit_specs?id=eq.${spec.id}&cut_qa_status=eq.pending`,headers:h,body:{cut_qa_status:'in_progress'},json:true}); if(!claim.length)return [];
const prompt=await this.helpers.httpRequest({method:'GET',url:`${$env.EDIT_SPEC_API_URL}/prompts/cut-qa-system`,json:true}); const cuts=[];
for(const [cut_index,cut] of spec.spec_json.cuts.entries()){if(!cut.keep)continue; const d=cut.end-cut.start; const timestamps=[cut.start,cut.start+d*.33,cut.start+d*.66,Math.max(cut.start,cut.end-.04)]; const f=await this.helpers.httpRequest({method:'POST',url:`${$env.EDIT_SPEC_API_URL}/video-frames`,body:{video_url:spec.spec_json.source_video.url,timestamps},json:true}); cuts.push({cut_index,timestamps,frames:f.frames});}
const content=[{type:'text',text:`Evalua todos los cortes. Timestamps fuente: ${JSON.stringify(cuts.map(c=>({cut_index:c.cut_index,timestamps:c.timestamps})))}`},...cuts.flatMap(c=>c.frames.map(f=>({type:'image',source:{type:'base64',media_type:f.media_type,data:f.data}})))];
const response=await this.helpers.httpRequest({method:'POST',url:'https://api.anthropic.com/v1/messages',headers:{'x-api-key':$env.ANTHROPIC_API_KEY,'anthropic-version':$env.ANTHROPIC_VERSION||'2023-06-01','content-type':'application/json'},body:{model:$env.EDIT_DIRECTOR_MODEL,max_tokens:4000,temperature:0,system:prompt.text,messages:[{role:'user',content}]},json:true}); const text=(response.content||[]).map(b=>b.text||'').join('').trim().replace(/^```json\s*|```$/gi,''); const parsed=JSON.parse(text);
if(!Array.isArray(parsed.results)||parsed.results.length!==cuts.length)throw new Error('QA visual no devolvio un resultado por corte keep:true');
const expected=new Set(cuts.map(c=>c.cut_index)); for(const result of parsed.results){if(!expected.has(result.cut_index)||typeof result.ok!=='boolean')throw new Error('QA visual devolvio cut_index u ok invalido'); if(!result.ok&&(!Number.isFinite(result.flagged_frame_time)||!result.reason))throw new Error('Corte marcado sin timestamp o motivo');}
return [{json:{spec,cuts,results:parsed.results}}];

const h={apikey:$env.SUPABASE_SERVICE_ROLE_KEY,Authorization:`Bearer ${$env.SUPABASE_SERVICE_ROLE_KEY}`,'Content-Type':'application/json'},now=new Date().toISOString(); const {spec,cuts,results}=$json;
await this.helpers.httpRequest({method:'POST',url:`${$env.SUPABASE_URL}/rest/v1/cut_qa_results`,headers:h,body:results.map(r=>({edit_spec_id:spec.id,cut_index:r.cut_index,ok:r.ok,flagged_frame_time:r.flagged_frame_time,reason:r.reason,checked_at:now})),json:true}); const flagged=results.filter(r=>!r.ok); const status=flagged.length?'flagged':'passed';
await this.helpers.httpRequest({method:'PATCH',url:`${$env.SUPABASE_URL}/rest/v1/edit_specs?id=eq.${spec.id}`,headers:h,body:{cut_qa_status:status,cut_qa_checked_at:now},json:true});
if(!flagged.length){await this.helpers.httpRequest({method:'PATCH',url:`${$env.SUPABASE_URL}/rest/v1/raw_videos?id=eq.${spec.raw_video_id}`,headers:h,body:{status:'edit_spec_ready',cut_qa_feedback:null},json:true});return [{json:{edit_spec_id:spec.id,cut_qa_status:'passed'}}];}
const clients=await this.helpers.httpRequest({method:'GET',url:`${$env.SUPABASE_URL}/rest/v1/clients?id=eq.${spec.client_id}&select=telegram_chat_id`,headers:h,json:true}); const chatId=clients[0]?.telegram_chat_id||$env.TELEGRAM_CHAT_ID;
for(const r of flagged){const cut=cuts.find(c=>c.cut_index===r.cut_index);const frame=cut.frames.reduce((a,b)=>Math.abs(b.timestamp-r.flagged_frame_time)<Math.abs(a.timestamp-r.flagged_frame_time)?b:a);await this.helpers.httpRequest({method:'POST',url:`https://api.telegram.org/bot${$env.TELEGRAM_BOT_TOKEN}/sendPhoto`,formData:{chat_id:String(chatId),caption:`Corte ${r.cut_index} - t=${r.flagged_frame_time}s: ${r.reason}`,photo:{value:Buffer.from(frame.data,'base64'),options:{filename:`cut-${r.cut_index}.jpg`,contentType:frame.media_type}}}});}
await this.helpers.httpRequest({method:'POST',url:`https://api.telegram.org/bot${$env.TELEGRAM_BOT_TOKEN}/sendMessage`,body:{chat_id:chatId,text:`QA visual marco ${flagged.length} corte(s) del edit_spec ${spec.id}.`,reply_markup:{inline_keyboard:[[{text:'Aprobar igual',callback_data:`cqap:${spec.id}`},{text:'Pedir regenerar ese corte',callback_data:`cqrg:${spec.id}`}]]}},json:true}); return [{json:{edit_spec_id:spec.id,cut_qa_status:'flagged'}}];

const u=$json.body||$json,cb=u.callback_query;if(!cb)return [{json:{skip:true}}];const [action,id]=(cb.data||'').split(':');if(!['cqap','cqrg'].includes(action))return [{json:{skip:true}}];const h={apikey:$env.SUPABASE_SERVICE_ROLE_KEY,Authorization:`Bearer ${$env.SUPABASE_SERVICE_ROLE_KEY}`,'Content-Type':'application/json'};
const rows=await this.helpers.httpRequest({method:'GET',url:`${$env.SUPABASE_URL}/rest/v1/edit_specs?id=eq.${id}&cut_qa_status=eq.flagged&select=id,raw_video_id,client_id`,headers:h,json:true});if(!rows.length)return [{json:{skip:true,reason:'already_decided'}}];
const reviewerId=String(cb.from?.id||'');const reviewers=await this.helpers.httpRequest({method:'GET',url:`${$env.SUPABASE_URL}/rest/v1/reviewers?client_id=eq.${rows[0].client_id}&telegram_user_id=eq.${encodeURIComponent(reviewerId)}&active=eq.true&select=id`,headers:h,json:true});if(!reviewers.length){try{await this.helpers.httpRequest({method:'POST',url:`https://api.telegram.org/bot${$env.TELEGRAM_BOT_TOKEN}/answerCallbackQuery`,body:{callback_query_id:cb.id,text:'Sin permiso para este cliente'},json:true});}catch{}return [{json:{skip:true,reason:'not_a_reviewer'}}];
if(action==='cqap'){await this.helpers.httpRequest({method:'PATCH',url:`${$env.SUPABASE_URL}/rest/v1/edit_specs?id=eq.${id}`,headers:h,body:{cut_qa_status:'passed'},json:true});await this.helpers.httpRequest({method:'PATCH',url:`${$env.SUPABASE_URL}/rest/v1/raw_videos?id=eq.${rows[0].raw_video_id}`,headers:h,body:{status:'edit_spec_ready'},json:true});}
else{const rr=await this.helpers.httpRequest({method:'GET',url:`${$env.SUPABASE_URL}/rest/v1/cut_qa_results?edit_spec_id=eq.${id}&ok=eq.false&select=cut_index,flagged_frame_time,reason&order=checked_at.desc`,headers:h,json:true});const feedback=`QA visual rechazo cortes: ${JSON.stringify(rr)}`;await this.helpers.httpRequest({method:'PATCH',url:`${$env.SUPABASE_URL}/rest/v1/edit_specs?id=eq.${id}`,headers:h,body:{status:'rejected_cut_qa'},json:true});await this.helpers.httpRequest({method:'PATCH',url:`${$env.SUPABASE_URL}/rest/v1/raw_videos?id=eq.${rows[0].raw_video_id}`,headers:h,body:{status:'assets_ready',cut_qa_feedback:feedback},json:true});}
await this.helpers.httpRequest({method:'POST',url:`https://api.telegram.org/bot${$env.TELEGRAM_BOT_TOKEN}/answerCallbackQuery`,body:{callback_query_id:cb.id,text:action==='cqap'?'Aprobado para render':'Reencolado en Capa 3'},json:true});return [{json:{edit_spec_id:id,decision:action}}];

const source=$json.spec||$json; const id=source.id||source.edit_spec_id;
if(id)await this.helpers.httpRequest({method:'PATCH',url:`${$env.SUPABASE_URL}/rest/v1/edit_specs?id=eq.${id}&cut_qa_status=eq.in_progress`,headers:{apikey:$env.SUPABASE_SERVICE_ROLE_KEY,Authorization:`Bearer ${$env.SUPABASE_SERVICE_ROLE_KEY}`,'Content-Type':'application/json'},body:{cut_qa_status:'pending'},json:true});
